from taf.sbts.oam.sc.rest.provider import ASIRProvider


class ASIRConnection(object):
    def __init__(self, host, port, username, password, asir_version="ASIR_22R3", secure=False, scope='write'):
        """
        Provide connection and authorization to ASIR Webem.

        :param str host: IP address to proper host, f.e. `127.0.0.1`.
        :param int port: Port for connection to ASIR Webem.
        :param str username: username to ASIR Webem authentication
        :param str password: password to ASIR Webem authentication
        :param str asir_version: Name of ASIR interface version. Set to the newest by default.
        Available releases: [ASIR_22R3]
        :param bool secure: verify SSL certificate
        :param str scope: read/write
        """
        self._asir = ASIRProvider.create_asir(host=host,
                                              port=port,
                                              username=username,
                                              password=password,
                                              asir_version=asir_version,
                                              secure=secure,
                                              scope=scope)

    def disconnect(self):
        """
        Close connection to ASIR Webem.

        :return: None
        """
        self._asir.sec.logout()

    def refresh_token(self, scope='write'):
        self._asir.refresh_token(scope=scope)

    def get_number_of_logged_in_users(self):
        """
        Get number of logged users in ASIR Webem.

        :return str: Number of logged users
        """
        return self._asir.get_number_of_logged_in_users()

    def get_site_info(self):
        """
        Get ASIR Webem site info.

        :return SiteInfoSMV1: ASIR Webem site info object
        """
        return self._asir.get_site_info()

    def upload_plan(self, scf_path):
        """
        Upload ASIR Webem plan file.

        :param str scf_path: path to '.xml' configuration file
        :return StagedPlanInfoCMV1: ASIR Webem staged plan object
        """
        return self._asir.upload_plan(scf_path)

    def upload_plan_template(self, delta_plan_id, scf_path):
        """
        Upload ASIR Webem plan file as template into delta plan buffer.

        :param str delta_plan_id: id of staged delta plan to delete
        :param str scf_path: path to '.xml' configuration file
        :return LoadPlanTemplateInfoCMV1: ASIR Webem loaded plan template object
        """
        return self._asir.upload_plan_template(delta_plan_id, scf_path)

    def get_staged_plans(self):
        """
        Get ASIR Webem uploaded plans info.

        :return list[StagedPlanInfoCMV1]: ASIR Webem staged plans info - list of objects
        """
        return self._asir.get_staged_plans()

    def delete_staged_plan(self, plan_id):
        """
        Delete ASIR Webem staged plan defined by plan id.

        :param str plan_id: id of staged plan to delete
        :return: None
        """
        return self._asir.delete_staged_plan(plan_id)

    def validate_plan(self, plan_id, timeout=60):
        """
        Validate ASIR Webem staged plan defined by plan id.

        :param str plan_id: id of staged plan to validate
        :param float timeout: time in seconds to finish the plan operation
        :return dict: information about result of plan validation operation. Example return value:
        {"restartNeeded": true, "message": "All parameters have passed validation."}
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._asir.validate_plan(plan_id, timeout)

    def get_validation_results(self, plan_id=None, job_id=None):
        """
        Get ASIR Webem validation results.

        :param str plan_id: id of staged plan to validate. If not passed latest plan_id will be used
        :param str job_id: id of validation job. If not passed latest job_id will be used
        :return str: information about result of plan validation operation. Example return value:
            {
                "location":"/api/v1/cm/plans/staged/1/jobs/7/validation-result/errors",
                "message":"Invalid plan file"
            }
        """
        return self._asir.get_validation_results(plan_id, job_id)

    def get_validation_errors(self, plan_id=None, job_id=None):
        """
        Get ASIR Webem validation errors results.

        :param str plan_id: id of staged plan to validate. If not passed latest plan_id will be used
        :param str job_id: id of validation job. If not passed latest job_id will be used
        :return list: information about result of plan validation operation. Example return value:
            [{
                "description":"ASI-1/SECPRM-1 is not valid: Can't serialize message of type 'asi.secprm_t' because it
                    is missing required fields: actNe3sOperationLogging. Please check if planfile is migrated.",
                "global":true,
                "severity":"error"
            }]
        """
        return self._asir.get_validation_errors(plan_id, job_id)

    def migrate_nidd(self, delta_plan_id, nidd_target_version=None, timeout=60):
        """
        Migrate ASIR Webem plan template to target NIDD version.

        :param str delta_plan_id: id of staged delta plan to delete
        :param str nidd_target_version: target NIDD version, if not provided newest release NIDD will be choosen
        :param float timeout: time in seconds to finish the plan migration
        :return CmEditorOperationInfoCMV1: information about result of plan template migration
        """
        return self._asir.migrate_nidd(delta_plan_id, nidd_target_version, timeout)

    def activate_plan(self, plan_id, timeout=60):
        """
        Activate ASIR Webem staged plan defined by plan id.

        :param str plan_id: id of staged plan to activate
        :param float timeout: time in seconds to finish the plan operation
        :return dict: information about result of plan activation operation. Example return value:
        {"restartNeeded": true, "message": "All parameters have passed validation."}
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._asir.activate_plan(plan_id, timeout)

    def create_new_delta_plan(self, source_plan, source_plan_id, timeout):
        """
        Create ASIR Webem delta plan from defined source.

        :param str source_plan: source of delta plan, possible values: ["none", "active", "staged"]
        :param str source_plan_id: id of source staged plan for new delta plan
        :param float timeout: time in seconds to finish the delta plan operation
        :return AllocatedEditingBufferID: ASIR Webem delta plan object
        """
        return self._asir.create_new_delta_plan(source_plan, source_plan_id, timeout)

    def get_staged_delta_plans(self):
        """
        Get ASIR Webem uploaded delta plans info.

        :return list[StagedDeltaPlanInfoCMV1]: list of ASIR Webem staged delta plan objects
        """
        return self._asir.get_staged_delta_plans()

    def delete_delta_plan(self, delta_plan_id):
        """
        Delete ASIR Webem staged delta plan defined by delta plan id.

        :param str delta_plan_id: id of staged delta plan to delete
        :return: None
        """
        return self._asir.delete_delta_plan(delta_plan_id)

    def update_parameter_of_delta_plan(self, delta_plan_id, operation, dn, name, field, index, value):
        """
        Update parameter of ASIR Webem staged delta plan.

        :param str delta_plan_id: id of staged delta plan
        :param str operation: modification operation, possible values: ["create", "update", "delete"]
        :param str dn: dist name of parameter
        :param str name: name of target parameter
        :param str value: new value of target parameter
        :return: None
        """
        return self._asir.update_parameter_of_delta_plan(delta_plan_id, operation, dn, name, field, index, value)

    def update_object_of_delta_plan(self, delta_plan_id, body):
        """
        create/delete object of ASIR.

        :param str delta_plan_id: id of staged delta plan
        :param list body: in format:
        [
            {"operation":"create","dn":"ASI-1","moc":"HUBMOD","instanceId":1},
            {"operation":"create","dn":"ASI-1","moc":"HUBMOD"}
        ]
        :return: None
        """
        return self._asir.update_object_of_delta_plan(delta_plan_id, body)

    def activate_delta_plan(self, delta_plan_id, timeout=60):
        """
        Activate ASIR Webem staged delta plan defined by delta plan id.

        :param str delta_plan_id: id of staged delta plan to activate
        :param float timeout: time in seconds to finish the delta plan operation
        :return DeltaPlanActivationInfoCMV1: delta plan activation result object
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._asir.activate_delta_plan(delta_plan_id, timeout)

    def reset_configuration(self):
        """
        Perform reset of actual ASIR Webem configuration.

        :return: None
        """
        return self._asir.reset_configuration()

    def get_active_alarms(self):
        """
        Get ASIR Webem active alarms info.

        :return list[AlarmInfoFMV1]: ASIR Webem active alarms info - list of objects
        """
        return self._asir.get_active_alarms()

    def get_cleared_alarms(self):
        """
        Get ASIR Webem cleared alarms info.

        :return list[AlarmInfoFMV1]: ASIR Webem active alarms info - list of objects
        """
        return self._asir.get_cleared_alarms()

    def get_active_software_info(self):
        """
        Get ASIR Webem active software info.

        :return SoftwareInfoSWMV1: ASIR Webem active software info object
        """
        return self._asir.get_active_software_info()

    def get_passive_software_info(self):
        """
        Get ASIR Webem passive software info.

        :return SoftwareInfoSWMV1: ASIR Webem passive software info object
        """
        return self._asir.get_passive_software_info()

    def get_factory_software_info(self):
        """
        Get ASIR Webem factory software info.

        :return SoftwareInfoSWMV1: ASIR Webem factory software info object
        """
        return self._asir.get_factory_software_info()

    def get_active_dist_names(self):
        """
        Get ASIR Webem active dist names.

        :return list: ASIR Webem active dist names
        """
        return self._asir.get_active_dist_names()

    def get_unit_logical_info(self, uid):
        """
        Get ASIR Webem unit logical info.

        :param str uid: Unit ID
        :return TopologyUnitInfoTOPOLGYV1: ASIR Webem unit logical info
        """
        return self._asir.get_unit_logical_info(uid)

    def get_unit_physical_info(self, uid):
        """
        Get ASIR Webem unit physical info.

        :param str uid: Unit ID
        :return TopologyUnitInfoTOPOLGYV1: ASIR Webem unit physical info
        """
        return self._asir.get_unit_physical_info(uid)

    def get_unit_available_operations(self, uid):
        """
        Get ASIR Webem unit available operations.

        :param str uid: Unit ID
        :return UnitAvailableOperationsSMV1: ASIR Webem unit available operations
        """
        return self._asir.get_unit_available_operations(uid)

    def get_site_logical_info(self):
        """
        Get site logical info from ASIR Webem.

        :return list[HwObjectTOPOLGYV1]: ASIR Webem logical site info - list of objects
        """
        return self._asir.get_site_logical_info()

    def get_site_physical_info(self):
        """
        Get site physical info from ASIR Webem.

        :return list[HwObjectTOPOLGYV1]: ASIR Webem physical site info - list of objects
        """
        return self._asir.get_site_physical_info()

    def perform_operation_on_unit(self, uid, operation, timeout):
        """
        Perform operation with defined ASIR Webem unit.

        :param str uid: Unit ID
        :param str operation: ASIR Webem operation
        :param float timeout: time in seconds to finish the plan operation
        :return UnitOperationResultSMV1: ASIR Webem unit available operations
        """
        return self._asir.perform_operation_on_unit(uid, operation, timeout)

    def get_active_scf_file(self, local_dir_path, file_name, timeout):
        """
        Save current SCF to file and get the path to this file.

        :return str: Path to the file with current SCF content.
        """
        return self._asir.get_active_scf_file(local_dir_path=local_dir_path, file_name=file_name, timeout=timeout)

    def get_all_software_packages(self):
        """
        Get all software packages installed in the BTS

        :return list: list of software versions
        """
        return self._asir.get_all_software_packages()

    def get_delta_plan_file(self, delta_plan_id, content_type, local_dir_path, timeout, file_name=None):
        """
        Get ASIR Webem staged delta plan.

        :return str: Path to ASIR delta file.
        """
        return self._asir.get_delta_plan_file(delta_plan_id, content_type, local_dir_path, timeout, file_name)
